def load_original(name):
    filename, _, encoded = PAYLOADS[name]
    source = zlib.decompress(base64.b85decode(encoded)).decode('utf-8')
    mod = types.ModuleType('isolated_' + name)
    mod.__file__ = filename
    mod.__package__ = None
    sys.modules[mod.__name__] = mod  # required by dataclasses in GOLD strategy
    # __name__ != '__main__' prevents original standalone auto-run.
    exec(compile(source, filename, 'exec'), mod.__dict__)
    return mod

def top100_single_cycle(mod):
    # The original cmd_paper() is a FOREVER loop. Execute its exact cycle
    # once so all six strategies can run in a scheduled GitHub job.
    class Args:
        tf = '15m'
        top = mod.TOP_N
        min_score = 6
        no_htf = False
    args = Args()
    st = mod.load_state()
    syms = mod.get_top_symbols(args.top)
    results = mod.scan_all(syms, args.tf)
    mod.manage_positions(st, results)
    mod.open_new(st, results, args)
    mod.save_state(st)
    wr = (st['wins'] / st['closed'] * 100) if st['closed'] else 0
    print(f"TOP100 paper cycle complete | equity={st['equity']:.2f} open={len(st['positions'])} closed={st['closed']} win%={wr:.1f}")

def run_one(name):
    print('\n' + '=' * 70 + '\nSTART ' + name + '\n' + '=' * 70, flush=True)
    try:
        mod = load_original(name)
        entry = PAYLOADS[name][1]
        if entry == 'top100_once':
            top100_single_cycle(mod)
        else:
            getattr(mod, entry)()
        print('FINISHED', name, flush=True)
        return True
    except Exception:
        print('FAILED', name, flush=True)
        traceback.print_exc()
        return False

def main():
    parser = argparse.ArgumentParser(description='Six isolated ORIGINAL paper trading strategies in one .py')
    parser.add_argument('--only', choices=list(PAYLOADS))
    parser.add_argument('--list', action='store_true')
    args = parser.parse_args()
    if args.list:
        for name, (file, _, _) in PAYLOADS.items():
            print(f'{name}: {file}')
        return
    names = [args.only] if args.only else list(PAYLOADS)
    outcomes = {name: run_one(name) for name in names}
    print('\nSUMMARY:', ', '.join(f'{name}={"OK" if ok else "FAILED"}' for name, ok in outcomes.items()))
    if not all(outcomes.values()):
        sys.exit(1)

if __name__ == '__main__':
    main()
